$ErrorActionPreference='Stop'
$d='C:\Temp\PBTear26_cont_fine_snapshot02'
if((Test-Path "$d\tear.lock") -or (Test-Path "$d\post.lock")){throw 'Runtime still active'}
if((Test-Path "$d\post.out") -or (Test-Path "$d\post.dat")){throw 'Post files exist; inspect before any retry'}
if(-not (Test-Path "$d\tear.rst")){throw 'Result file absent'}
if(-not (Test-Path "$d\model.db")){throw 'Database absent'}
$l=& 'C:\Program Files\ANSYS Inc\v261\licensingclient\winx64\lmutil.exe' lmstat -f preppost -c 1055@MARCDNICHITBF25
if(($l -join "`n") -notmatch 'Total of 0 licenses? in use'){throw 'PrepPost unavailable'}
if((Get-FileHash "$d\NATIVE_SNAPSHOT.json").Hash.ToLower() -ne '67bd9b2d3a59e2497169e4d24e03f91ad0cc73f0fa94ce7be74fd6e6c4f69c8c'){throw 'Snapshot record changed'}
$rst=Get-Item "$d\tear.rst"
if($rst.Length -ne 2109014016 -or $rst.LastWriteTimeUtc.Ticks -ne 639269571744823310){throw 'Snapshot result changed'}
if((Get-FileHash "$d\model.db").Hash.ToLower() -ne '2ada98f99d3223ad12a2856eeb3032be9c33a07d0331f92668804526d84b6a0d'){throw 'Snapshot database changed'}

[IO.File]::WriteAllBytes("$d\post.dat",[Convert]::FromBase64String(''))
if((Get-FileHash "$d\post.dat").Hash.ToLower() -ne '99c1186ee1a622f1439754e67fd1f1b503d9ec0d63f1b380c314483f627bf75b'){throw 'Post hash mismatch'}
$p=Start-Process 'C:\Program Files\ANSYS Inc\v261\ansys\bin\winx64\ANSYS261.exe' -ArgumentList '-b nolist -s noread -smp -np 1 -p preppost -j post -i post.dat -o post.out' -WorkingDirectory $d -PassThru
$p.Id
